/**
 * Synchronous stdout/stderr plumbing.
 *
 * CPython's `print()` and the interpreter's traceback writer both emit their
 * text before the process dies, and ordering between the two streams matters
 * (e.g. bencoder prints a byte value to stdout and *then* raises). Node's
 * `process.stdout.write` may buffer asynchronously on pipes, so writes issued
 * right before `process.exit()` can be lost. We therefore go straight to the
 * file descriptors with `fs.writeSync`, which accepts a plain string.
 */

import * as fs from 'node:fs';

const FD_STDOUT = 1;
const FD_STDERR = 2;

/**
 * UTF-8 length of a JS string, computed from code points so that partial
 * writes can be resumed at a character boundary.
 */
function utf8Length(text) {
  let total = 0;
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) total += 1;
    else if (cp < 0x800) total += 2;
    else if (cp < 0x10000) total += 3;
    else total += 4;
  }
  return total;
}

/** Character index that corresponds to `byteCount` UTF-8 bytes of `text`. */
function charIndexForByteOffset(text, byteCount) {
  let bytes = 0;
  let index = 0;
  for (const ch of text) {
    if (bytes >= byteCount) break;
    const cp = ch.codePointAt(0);
    bytes += cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
    index += ch.length;
  }
  return index;
}

function writeAll(fd, text) {
  let pending = text;
  while (pending.length > 0) {
    let written;
    try {
      written = fs.writeSync(fd, pending, null, 'utf8');
    } catch (err) {
      // Non-blocking pipes and signal interruptions are retryable.
      if (err && (err.code === 'EAGAIN' || err.code === 'EINTR')) continue;
      if (err && err.code === 'EPIPE') return; // reader went away, like SIGPIPE
      throw err;
    }
    if (written >= utf8Length(pending)) return;
    pending = pending.slice(charIndexForByteOffset(pending, written));
  }
}

export function writeStdout(text) {
  writeAll(FD_STDOUT, text);
}

export function writeStderr(text) {
  writeAll(FD_STDERR, text);
}

/** Equivalent of CPython's `print(value)` for an already-stringified value. */
export function printLine(text) {
  writeStdout(`${text}\n`);
}

/** Terminate with `code`; all of our writes are already flushed. */
export function exitWith(code) {
  process.exit(code);
}

