/**
 * Argument-parser errors, mirroring `argparse.ArgumentError` and the
 * `SystemExit` that `parser.error()` / the help action raise.
 */

/** `argparse.ArgumentError` — always reported through `parser.error()`. */
export class ArgumentError extends Error {
  /**
   * @param {{optionStrings: string[]}|null} action
   * @param {string} message
   */
  constructor(action, message) {
    super(message);
    this.actionName = action === null ? null : action.optionStrings.join('/');
    this.argparseMessage = message;
  }

  /** `str(err)` — what `parser.error()` receives. */
  toDisplayString() {
    if (this.actionName === null) return this.argparseMessage;
    return `argument ${this.actionName}: ${this.argparseMessage}`;
  }
}

/** `SystemExit`: carries the status plus anything already written. */
export class SystemExit extends Error {
  constructor(status) {
    super(`SystemExit: ${status}`);
    this.status = status;
  }
}

