/**
 * The two argparse actions this program needs: `store` (for `--a`) and `help`
 * (the automatic `-h/--help`).
 */

export const ACTION_STORE = 'store';
export const ACTION_HELP = 'help';

export class Action {
  /**
   * @param {{
   *   optionStrings: string[],
   *   dest: string,
   *   kind: string,
   *   nargs?: number|null,
   *   required?: boolean,
   *   help?: string|null,
   *   metavar?: string|null,
   * }} spec
   */
  constructor(spec) {
    this.optionStrings = spec.optionStrings;
    this.dest = spec.dest;
    this.kind = spec.kind;
    // `null` means "exactly one value"; `0` means "a flag".
    this.nargs = spec.nargs === undefined ? null : spec.nargs;
    this.required = spec.required === true;
    this.help = spec.help === undefined ? null : spec.help;
    this.metavar = spec.metavar === undefined ? null : spec.metavar;
  }

  /** `_get_default_metavar_for_optional` -> `dest.upper()`. */
  get displayMetavar() {
    return this.metavar === null ? this.dest.toUpperCase() : this.metavar;
  }

  /** `action.format_usage()` for a flag, or `--a A` for a value-taking option. */
  formatUsagePart() {
    const first = this.optionStrings[0];
    if (this.nargs === 0) return first;
    return `${first} ${this.displayMetavar}`;
  }

  /** `_format_action_invocation` — the left column of the help listing. */
  formatInvocation() {
    const joined = this.optionStrings.join(', ');
    if (this.nargs === 0) return joined;
    return `${joined} ${this.displayMetavar}`;
  }
}

export function createHelpAction() {
  return new Action({
    optionStrings: ['-h', '--help'],
