   */
  constructor(prog, actions) {
    this.prog = prog;
    this.actions = actions;
    this.width = terminalColumns() - 2;
    this.maxHelpPosition = Math.min(
      DEFAULT_MAX_HELP_POSITION,
      Math.max(this.width - 20, INDENT_INCREMENT * 2),
    );
    this.actionMaxLength = actions.reduce(
      (longest, action) => Math.max(longest, action.formatInvocation().length + INDENT_INCREMENT),
      0,
    );
  }

