    return `${text.replace(/^\n+/, '').replace(/\n+$/, '')}\n`;
  }

  /** `_format_usage` — returns `usage: ...\n\n`. */
  _usageBlock() {
    const prefix = 'usage: ';
    const parts = this.actions.map((action) => {
      const part = action.formatUsagePart();
      return action.required ? part : `[${part}]`;
    });

    let usage = [this.prog, ...parts].join(' ');
    const textWidth = Math.max(this.width, 11);

    if (prefix.length + usage.length > textWidth) {
      const indent = ' '.repeat(prefix.length);
      if (prefix.length + this.prog.length <= 0.75 * textWidth) {
        const hangingIndent = ' '.repeat(prefix.length + this.prog.length + 1);
        usage = joinWrapped([this.prog, ...parts], hangingIndent, textWidth, prefix).join('\n');
      } else {
        let lines = joinWrapped(parts, indent, textWidth, null);
        if (lines.length > 1) lines = joinWrapped(parts, indent, textWidth, null);
        usage = [this.prog, ...lines].join('\n');
      }
    }
    return `${prefix}${usage}\n\n`;
  }

  /** `_format_action` for one option row. */
  _formatAction(action) {
    const helpPosition = Math.min(this.actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - INDENT_INCREMENT - 2;
    const invocation = action.formatInvocation();

    if (action.help === null || action.help.trim() === '') {
      return `${' '.repeat(INDENT_INCREMENT)}${invocation}\n`;
    }

    let header;
    let firstIndent;
    if (invocation.length <= actionWidth) {
      header = `${' '.repeat(INDENT_INCREMENT)}${invocation.padEnd(actionWidth)}  `;
      firstIndent = 0;
    } else {
      header = `${' '.repeat(INDENT_INCREMENT)}${invocation}\n`;
      firstIndent = helpPosition;
    }

    const helpLines = wrapText(action.help, helpWidth);
    let out = header;
    out += `${' '.repeat(firstIndent)}${helpLines[0]}\n`;
    for (const line of helpLines.slice(1)) out += `${' '.repeat(helpPosition)}${line}\n`;
    return out;
  }
}

/** argparse's inner `get_lines()` helper from `_format_usage`. */
function joinWrapped(parts, indent, textWidth, prefix) {
  const lines = [];
  let line = [];
  let lineLength = (prefix === null ? indent.length : prefix.length) - 1;

  for (const part of parts) {
    if (lineLength + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLength = indent.length - 1;
    }
    line.push(part);
    lineLength += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (prefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
  return lines;
}

