/**
 * `argparse.HelpFormatter` for the option-only parser used by test4.
 *
 * Layout is width sensitive in exactly the same way CPython's is, including
 * the `COLUMNS`-driven terminal probe and the `max_help_position` clamp added
 * in 3.13 (`min(24, max(width - 20, indent_increment * 2))`). Setting
 * `COLUMNS=30` reproduces the reference program's wrapped output.
 */

const INDENT_INCREMENT = 2;
const DEFAULT_MAX_HELP_POSITION = 24;
const FALLBACK_COLUMNS = 80;

/** `shutil.get_terminal_size()`: `COLUMNS`, then stdout's tty, then (80, 24). */
export function terminalColumns() {
  const fromEnv = process.env.COLUMNS;
  if (fromEnv !== undefined && /^[ \t]*[+-]?\d+[ \t]*$/.test(fromEnv)) {
    const parsed = Number.parseInt(fromEnv.trim(), 10);
    if (parsed > 0) return parsed;
  }
  // CPython queries stdout even when the text is destined for stderr.
  if (process.stdout.isTTY && typeof process.stdout.columns === 'number' && process.stdout.columns > 0) {
    return process.stdout.columns;
  }
  return FALLBACK_COLUMNS;
}

/** `textwrap.wrap` for single-paragraph help text (greedy, breaks long words). */
export function wrapText(text, width) {
  const normalized = text.replace(/[\t\n\v\f\r ]+/g, ' ').trim();
  if (normalized === '') return [];

  const effective = Math.max(width, 1);
  const lines = [];
  let current = '';
  for (const word of normalized.split(' ')) {
    let pending = word;
    while (pending.length > effective) {
      if (current !== '') {
        lines.push(current);
        current = '';
      }
      lines.push(pending.slice(0, effective));
      pending = pending.slice(effective);
    }
    if (current === '') current = pending;
    else if (current.length + 1 + pending.length <= effective) current += ` ${pending}`;
    else {
      lines.push(current);
      current = pending;
    }
  }
  if (current !== '') lines.push(current);
  return lines;
}

export class HelpFormatter {
  /**
   * @param {string} prog
   * @param {import('./actions.mjs').Action[]} actions
   */
  constructor(prog, actions) {
    this.prog = prog;
    this.actions = actions;
    this.width = terminalColumns() - 2;
    this.maxHelpPosition = Math.min(
      DEFAULT_MAX_HELP_POSITION,
      Math.max(this.width - 20, INDENT_INCREMENT * 2),
    );
    this.actionMaxLength = actions.reduce(
      (longest, action) => Math.max(longest, action.formatInvocation().length + INDENT_INCREMENT),
      0,
    );
  }

  /** `formatter.add_usage(...)` + `format_help()` -> `usage: ...\n`. */
  formatUsage() {
    const block = this._usageBlock();
    return `${block.replace(/^\n+/, '').replace(/\n+$/, '')}\n`;
  }

  /** The whole `--help` payload. */
  formatHelp() {
    let text = this._usageBlock();
    text += 'options:\n';
    for (const action of this.actions) text += this._formatAction(action);
    // `format_help` collapses runs of blank lines and normalises the edges.
    text = text.replace(/\n\n\n+/g, '\n\n');
    return `${text.replace(/^\n+/, '').replace(/\n+$/, '')}\n`;
  }

  /** `_format_usage` — returns `usage: ...\n\n`. */
  _usageBlock() {
    const prefix = 'usage: ';
    const parts = this.actions.map((action) => {
      const part = action.formatUsagePart();
      return action.required ? part : `[${part}]`;
    });

    let usage = [this.prog, ...parts].join(' ');
    const textWidth = this.width; // `self._width - self._current_indent`, indent 0 here

    if (prefix.length + usage.length > textWidth) {
      if (prefix.length + this.prog.length <= 0.75 * textWidth) {
        // Hang the option list under the end of the program name.
        const hangingIndent = ' '.repeat(prefix.length + this.prog.length + 1);
        usage = joinWrapped([this.prog, ...parts], hangingIndent, textWidth, prefix).join('\n');
      } else {
        // Program name on its own line, options wrapped under the prefix.
        // (argparse re-splits optionals and positionals here; this parser has
        // no positionals, so the re-split is the same list.)
        const indent = ' '.repeat(prefix.length);
        usage = [this.prog, ...joinWrapped(parts, indent, textWidth, null)].join('\n');
