/**
 * Emulation of `linecache` + CPython's traceback caret arithmetic.
 *
 * A frozen build records its script as the *relative* path `test4.py`, so
 * whether a traceback shows the offending source line depends on the current
 * working directory:
 *
 *   $ cd /workspace/dataset && test4_executable --a x   # test4.py is here
 *     File "test4.py", line 8, in <module>
 *       result = bencoder.decode(args.a.encode('ascii'))  # Decode bencoded string
 *                ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
 *   $ cd /tmp && test4_executable --a x                  # nothing to read
 *     File "test4.py", line 8, in <module>
 *
 * Reproducing that means actually looking for `./test4.py`, which is what this
 * module does.
 */

import * as fs from 'node:fs';
import * as path from 'node:path';

/** `linecache.getline(filename, lineno)` — '' when unavailable. */
export function getLine(filename, lineNumber) {
  let text;
  try {
    text = fs.readFileSync(path.resolve(process.cwd(), filename), 'utf8');
  } catch {
    return '';
  }
  // Keep line endings, exactly like `str.splitlines(keepends=True)`.
  const lines = text.match(/[^\n]*\n|[^\n]+/g) ?? [];
  const line = lines[lineNumber - 1];
  return line === undefined ? '' : line;
}

/** UTF-8 byte length of a JS string. */
function utf8Length(text) {
  let total = 0;
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    total += cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
  }
  return total;
}

/**
 * `traceback._byte_offset_to_character_offset`: how many characters the first
 * `byteOffset` UTF-8 bytes of `text` decode to. A truncated final character
 * decodes to a single replacement character, and an offset past the end simply
 * yields the whole string's length.
 */
export function byteOffsetToCharacterOffset(text, byteOffset) {
  let bytes = 0;
  let characters = 0;
  for (const ch of text) {
    const width = utf8Length(ch);
    if (bytes + width > byteOffset) {
      // Partially consumed character -> one U+FFFD, but only if we actually
      // consumed part of it.
      return bytes < byteOffset ? characters + 1 : characters;
    }
    bytes += width;
    characters += 1;
  }
  return characters;
}

/**
 * Render the source line and caret underline for one traceback frame.
 *
 * @param {string} rawLine the line as read, newline included
 * @param {{colno: number, endColno: number}} span 0-based byte columns of the
 *   sub-expression that raised, as recorded in the code object
 * @returns {string[]} zero, one or two ready-to-emit lines
 */
export function formatSourceLines(rawLine, span) {
  const stripped = rawLine.trim();
  if (stripped === '') return [];

  const lines = [`    ${stripped}`];

  const strippedCharacters = rawLine.length - stripped.length;
  const startOffset = byteOffsetToCharacterOffset(rawLine, span.colno) + 1;
  const endOffset = byteOffsetToCharacterOffset(rawLine, span.endColno) + 1;

  // CPython hides the underline when it would span the whole line.
  if (endOffset - startOffset < stripped.length) {
    const leading = 4 + (startOffset - strippedCharacters);
    lines.push(' '.repeat(Math.max(leading, 0)) + '^'.repeat(Math.max(endOffset - startOffset, 0)));
  }
  return lines;
}

