cat > /tmp/gen.mjs <<'EOF'
// Deterministic LCG so runs are reproducible.
let seed = Number(process.argv[3] ?? 12345) >>> 0;
const rnd = () => ((seed = (seed * 1103515245 + 12345) >>> 0) / 2 ** 32);
const pick = (a) => a[Math.floor(rnd() * a.length)];
const ALPHA = [..."0123456789ildeo:-+ ,.'\"\\abcxyzEIL\t"];

function randValid(depth) {
  const kinds = depth > 3 ? ['int', 'str'] : ['int', 'str', 'list', 'dict'];
  switch (pick(kinds)) {
    case 'int': return 'i' + (rnd() < 0.2 ? '-' : '') + Math.floor(rnd() * 1e6) + 'e';
    case 'str': {
      const n = Math.floor(rnd() * 6);
      let body = '';
      for (let i = 0; i < n; i++) body += pick([..."abc:ilde019'\"\\ "]);
      const declared = rnd() < 0.25 ? n + Math.floor(rnd() * 5) : n;
      return `${declared}:${body}`;
    }
    case 'list': {
      let s = 'l';
      for (let i = Math.floor(rnd() * 3); i > 0; i--) s += randValid(depth + 1);
      return s + 'e';
    }
    default: {
      let s = 'd';
      for (let i = Math.floor(rnd() * 4); i > 0; i--) s += randValid(depth + 1);
      return s + 'e';
    }
  }
}
function mutate(s) {
  if (s.length === 0) return pick(ALPHA);
  const i = Math.floor(rnd() * s.length);
  switch (Math.floor(rnd() * 4)) {
    case 0: return s.slice(0, i) + pick(ALPHA) + s.slice(i);
    case 1: return s.slice(0, i) + s.slice(i + 1);
    case 2: return s.slice(0, i) + pick(ALPHA) + s.slice(i + 1);
    default: return s.slice(0, i);
  }
}
const q = (v) => "'" + v.split("'").join("'\\''") + "'";
const total = Number(process.argv[2] ?? 500);
const out = [];
for (let n = 0; n < total; n++) {
  const mode = n % 3;
  let v;
  if (mode === 0) { const L = Math.floor(rnd() * 24); v = ''; for (let i = 0; i < L; i++) v += pick(ALPHA); }
  else if (mode === 1) v = randValid(0);
  else { v = randValid(0); for (let k = 1 + Math.floor(rnd() * 2); k > 0; k--) v = mutate(v); }
  if (v.includes('\0')) continue;
  out.push(`--a ${q(v)}`);
}
process.stdout.write(out.join('\n') + '\n');
EOF
for s in 11 22 33 44; do node /tmp/gen.mjs 600 $s > /tmp/fuzz-mine-$s.txt; done
wc -l /tmp/fuzz-mine-*.txt
for s in 11 22 33 44; do printf 'seed %s: ' $s; bash /output/tools/difftest.sh /tmp/fuzz-mine-$s.txt 2>&1 | head -30; done
